vec2 logarithmic_spiral(in vec2 uv)
{
    float log_length = log(length(uv));
    return vec2(
         log_length + 4.0 * atan(uv.y, uv.x) * INV_TWO_PI,
        -log_length * HALF_PI * 0.25 + iTime * 0.025
    );
}

void mainImage( out vec4 O, in vec2 F )
{
    vec2 R = iResolution.xy,
        uv = (2.0 * F - R)/R.y;

    float ray_length = length(uv);
    float ray_angle  = atan(uv.y, uv.x);

    vec2 transformed_uv = logarithmic_spiral(uv);

    transformed_uv = fract(transformed_uv*2.0)-vec2(0.5);

    float length_transformed_uv = length(transformed_uv);
    float angle_transformed_uv = atan(transformed_uv.y, transformed_uv.x);

    float noise_value = texture(
        iChannel0,
        normalize(
            transformed_uv + vec2(angle_transformed_uv * INV_TWO_PI)
        )
    ).r;

    vec3 random_colour = vec3(
        1.85*random(floor(length(transformed_uv*40.0))),
        0.1,
        0.1
    );
    vec3 pixel = noise_value * 0.5 * (0.9+0.1*cos(noise_value+iTime)) * random_colour / length_transformed_uv;
    pixel *= 0.65*length(uv);
    O = vec4(gamma(pixel),1.0);
}

#define PI         3.141592653589793238462643383279
#define TWO_PI     6.283185307179586476925286766559
#define HALF_PI    1.570796326794896619231321691639
#define E          2.718281828459045235360287471352
#define INV_PI     0.318309886183790671537767526745
#define INV_TWO_PI 0.159154943091895335768883763372
#define TAU        TWO_PI

#define gamma(c) pow(c, vec3(1.0/2.2))

float random (float seed)
{
    return fract(sin(seed) * 43758.5453123);
}

float random (vec2 st)
{
    return fract(sin(dot(st.xy, vec2(12.9898,78.233)))*43758.5453123);
}

float hash21(vec2 p)
{
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p)
{
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}
